        path[0] = weth;
        path[1] = TARGET;

        // Approve router to spend WETH (we'll wrap BNB first)
        IWETH(weth).deposit{value: buyAmount}();
        IWETH(weth).approve(routerAddress, buyAmount);

        // Swap WETH for Honey
        IRouter(routerAddress).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            buyAmount,
            0,
            path,
            attacker,
            block.timestamp
        );

